INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-front-squat', 'Front Squat', 'strength', 'quads,glutes,core', 'barbell', 'Elbows high, chest proud. This keeps the bar secure and your spine stacked. Push the floor away to stand. Heel-elevated shoes help if ankles are tight.', 'https://www.youtube.com/watch?v=v-mQm_droHg', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-bench-press', 'Bench Press', 'strength', 'chest,shoulders,triceps', 'barbell,bench', 'Squeeze shoulder blades together like you''re holding a pencil. This protects your shoulders and builds a stronger press. Drive feet into the floor. Bar touches mid-chest.', 'https://www.youtube.com/watch?v=vcBig73ojpE', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-ohp', 'Overhead Press', 'strength', 'shoulders,triceps', 'barbell', 'Ribs down, squeeze glutes. This locks your core into a strong brace position. Bar starts at collarbone, press straight up. Head moves through at the top.', 'https://www.youtube.com/watch?v=_RlRDWO2jfg', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-bent-over-row', 'Bent Over Row', 'strength', 'back,biceps,rear_delts', 'barbell', 'Hinge at the hips, flat back, brace. Pull the weight to the lower chest, squeeze the shoulder blades together at the top, then lower under control. You should feel the upper and middle back working, not the low back. Builds upper-back strength.', 'https://www.youtube.com/watch?v=G8l_8chR5BE', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-rdl', 'Romanian Deadlift', 'strength', 'hamstrings,glutes,lower_back', 'barbell', 'Push hips back like closing a car door. This teaches the hip hinge pattern safely. Bar slides down your legs. Feel the stretch in your hamstrings, then squeeze glutes to stand.', 'https://www.youtube.com/watch?v=jEy_czb3RKA', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-block-pull', 'Block Pull', 'strength', 'back,glutes,hamstrings', 'barbell,blocks', 'Same as conventional deadlift but bar starts elevated. This lets you practice pulling mechanics with less range. Ribs down, push the floor away. Build to full range.', 'https://www.youtube.com/watch?v=ZR5t8K487dQ', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-deadlift', 'Conventional Deadlift', 'strength', 'back,glutes,hamstrings,quads', 'barbell', 'Push the floor away. Don''t think "pull the bar up." Ribs down, belt buckle to chin at lockout. Squeeze glutes at the top. You earned this progression.', 'https://www.youtube.com/watch?v=wYREQkVtvEc', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-incline-db-press', 'Incline DB Press', 'strength', 'chest,shoulders,triceps', 'dumbbell,bench', 'Bench at 30 degrees. Pin shoulder blades back. This protects your shoulders and builds a bigger chest. Press up without letting shoulders roll forward.', 'https://www.youtube.com/watch?v=8iPEnn-ltC8', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lateral-raise', 'Lateral Raise', 'strength', 'shoulders', 'dumbbell', 'Slight lean forward, lead with elbows. This targets the side delt and builds wider shoulders. Raise to shoulder height, control the descent. Light weight, high reps.', 'https://www.youtube.com/watch?v=3VcKaXpzqRo', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-ez-curl', 'EZ Bar Curl', 'strength', 'biceps,forearms', 'ez-bar', 'Elbows pinned to your sides. This isolates the biceps and prevents cheating. Squeeze at the top, slow descent. The angled grip is easier on your wrists.', 'https://www.youtube.com/watch?v=zG2xJ0Q5QtI', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-bulgarian-split-squat', 'Bulgarian Split Squat', 'strength', 'quads,glutes,balance', 'dumbbell,bench', 'Rear foot on bench, front foot far enough out that your knee stays over ankle. Lean slightly forward. This builds single-leg strength and fixes side-to-side imbalances.', 'https://www.youtube.com/watch?v=2C-uNgKwPLE', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-db-row', 'Dumbbell Row', 'strength', 'back,biceps,rear_delts', 'dumbbell,bench', 'One hand and knee on bench. Pull to hip, not shoulder. This targets the lats more. Squeeze the shoulder blade back at the top. Each side independently.', 'https://www.youtube.com/watch?v=roCP6wCXPqo', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-tricep-pushdown', 'Tricep Pushdown', 'strength', 'triceps', 'cable', 'Elbows locked at your sides. This isolates the triceps. Squeeze at full extension. Control the return. Rope attachment gives the best range of motion.', 'https://www.youtube.com/watch?v=2-LAMcpzODU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-hammer-curl', 'Hammer Curl', 'strength', 'biceps,brachioradialis,forearms', 'dumbbell', 'Neutral grip (palms face each other). This targets the brachioradialis and builds forearm strength for clinch work. Slow and controlled both directions.', 'https://www.youtube.com/watch?v=zC3nLlEvin4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-face-pulls', 'Face Pulls', 'strength', 'rear_delts,rotator_cuff,traps', 'cable,band', 'Rope at about face height. Pull toward your face with the elbows high, and turn the hands out so they finish beside the ears, pinkies back. Light and controlled. You should feel the back of the shoulders and between the shoulder blades. Trains the rear delts and rotator cuff.', 'https://www.youtube.com/watch?v=rep-qVOkqgk', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-pull-aparts', 'Band Pull-Aparts', 'strength', 'rear_delts,rhomboids,traps', 'band', 'Band at arm''s length, pull apart until it touches your chest. This wakes up the muscles between your shoulder blades. High reps, every session warmup.', 'https://www.youtube.com/watch?v=JObYtU7Y7ag', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pullup-band', 'Pull-Up (Band Assisted)', 'strength', 'back,biceps,core', 'pull-up bar,band', 'Full dead hang at bottom, chin clears bar at top. The band assists the hardest part. Pull with your lats, not just arms. Progress to thinner bands over time.', 'https://www.youtube.com/watch?v=4yE-XGDWJPg', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pullup-negative', 'Pull-Up (Negative)', 'strength', 'back,biceps,core', 'pull-up bar', 'Jump to top, lower yourself as slowly as possible. Aim for 5 seconds down. This builds the strength for real pull-ups faster than bands alone.', 'https://www.youtube.com/watch?v=4yE-XGDWJPg', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pullup', 'Pull-Up', 'strength', 'back,biceps,core', 'pull-up bar', 'Dead hang, shoulder-width grip. Pull until your chin clears the bar, then lower under control to a full hang. You should feel the lats and upper back doing the work, not just the arms. Builds back and grip strength for clinch work.', 'https://www.youtube.com/watch?v=eGo4IYlbE5g', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-ab-wheel', 'Ab Wheel Roll-Out', 'core', 'abs,lats,shoulders', 'ab wheel', 'Squeeze glutes and brace hard. Roll out only as far as you can without your lower back dipping. This is the highest EMG activation core exercise you can do.', 'https://www.youtube.com/watch?v=rqiTPdK1c_I', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-hanging-leg-raise', 'Hanging Leg Raise', 'core', 'lower_abs,hip_flexors', 'pull-up bar', 'Dead hang, raise legs to parallel without swinging. This forces your abs to work against gravity. Bend knees if straight legs are too hard. Posterior pelvic tilt at the top.', 'https://www.youtube.com/watch?v=Pr1ieGZ5atk', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pallof-press', 'Pallof Press', 'core', 'abs,obliques', 'cable,band', 'Stand sideways to cable, press hands straight out and resist the rotation. This builds the anti-rotation stability that protects your spine during strikes and clinch.', 'https://www.youtube.com/watch?v=AH_QZLm_0-s', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-side-plank-lift', 'Side Plank Hip Lift', 'core', 'obliques,glutes', 'bodyweight', 'Side plank on elbow, drop hip to floor and lift. This builds the lateral stability that powers kicks and resists sweeps. Each side independently.', 'https://www.youtube.com/watch?v=UhgQi_cz5zA', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-body-saw', 'Body Saw', 'core', 'abs,shoulders', 'sliders,towel', 'Forearm plank with feet on sliders, rock backward and forward. The further back, the harder. Keep ribs down and hips locked. One of the highest-demand plank variations.', 'https://www.youtube.com/watch?v=R9HJnAdJAUs', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-cable-woodchop', 'Cable Woodchop', 'core', 'obliques,abs,shoulders', 'cable', 'High-to-low or low-to-high. Rotate through your core, not your arms. Your hips and shoulders create the rotation. This builds the rotational power behind every strike.', 'https://www.youtube.com/watch?v=pAplQXk3dkU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-weighted-dead-bug', 'Weighted Dead Bug', 'core', 'abs,hip_flexors', 'dumbbell', 'Hold a weight overhead, opposite arm and leg extend. Your lower back stays glued to the floor. This teaches your core to stabilize while your limbs move, exactly like fighting.', 'https://www.youtube.com/watch?v=4XLEnwUr1d8', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-suitcase-carry', 'Suitcase Carry', 'core', 'obliques,grip,traps', 'dumbbell,kettlebell', 'Heavy weight in one hand, walk tall without leaning. This builds the anti-lateral flexion strength that keeps you upright in the clinch. Switch sides each set.', 'https://www.youtube.com/watch?v=tNHdx7pmrGI', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-foam-roll-pecs', 'Foam Roll Pecs', 'posture', 'chest', 'lacrosse ball,wall', 'Ball against a wall, lean into the front of the chest. Roll slowly over tender spots and breathe. Short-term comfort and range, not a posture fix.', 'https://www.youtube.com/watch?v=a8KjvtbkM8E', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-foam-roll-traps', 'Foam Roll Upper Traps', 'posture', 'traps,neck', 'lacrosse ball,wall', 'Ball between the wall and the top of the shoulder, lean in and roll slowly with easy pressure. It can ease tension for a while; it does not change the muscle.', 'https://www.youtube.com/watch?v=RcwfX-YKnIw', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-foam-roll-hip-flexors', 'Foam Roll Hip Flexors', 'posture', 'hip_flexors,quads', 'foam roller', 'Face down, roller on the front of the hip. Roll slowly from the hip crease to mid-thigh. Short-term comfort before a stretch.', 'https://www.youtube.com/watch?v=z4JbDQHJ_2M', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-doorway-pec-stretch', 'Doorway Pec Stretch', 'posture', 'chest,front_delts', 'doorway', 'Forearm on the door frame, elbow at or just above shoulder height. One side at a time. Step through gently until you feel the front of the chest, nothing sharp in the shoulder. Hold 30s and breathe.', 'https://www.youtube.com/watch?v=wwKWBwj-05U', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-hip-flexor-stretch', 'Half-Kneeling Hip Flexor Stretch', 'posture', 'hip_flexors,psoas', 'bodyweight', 'Back knee down, squeeze that glute and tuck your tailbone under. You should feel a gentle stretch in the front of the back hip. Optional after long sitting; nice, not a back-pain fix.', 'https://www.youtube.com/watch?v=YQmpO9VT2X4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-ytw-raises', 'Y-T-W Raises', 'posture', 'lower_traps,rear_delts,rotator_cuff', 'bodyweight', 'Face down or bent over. Make Y, T and W shapes with the arms, thumbs up, shoulder blades back and down. Slow and light. Trains the middle and lower trapezius.', 'https://www.youtube.com/watch?v=VCPp1DUypo0', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-chin-tucks', 'Chin Tucks', 'posture', 'deep_neck_flexors', 'bodyweight', 'Start lying on your back, head on the floor or a folded towel. Nod gently, as if saying "yes", so the back of the neck lengthens. Not a hard double chin. Hold 10s, 10 times. Trains the deep neck flexors. Progress to sitting against a wall.', 'https://www.youtube.com/watch?v=wQylqaCl8Zo', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-wall-angels', 'Wall Angels', 'posture', 'thoracic_spine,shoulders', 'wall', 'Back against the wall, arms in goalpost position. Slide up and down, and only go as high as you can keep contact with the wall. Gentle shoulder and upper-back range.', 'https://www.youtube.com/watch?v=M_ooIhKYs7c', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-glute-bridges', 'Glute Bridges', 'posture', 'glutes,core', 'bodyweight', 'Squeeze the glutes to lift, don''t push through your lower back. Ribs down, tuck the tailbone slightly. Hold 2 seconds at the top. Builds hip extension strength.', 'https://www.youtube.com/watch?v=tl6xvm4-Qk0', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-dead-bugs', 'Dead Bugs', 'posture', 'abs,hip_flexors,core', 'bodyweight', 'Lower back pressed into the floor. Opposite arm and leg extend out. If your back arches, you went too far. This teaches your core to stabilize your spine during movement.', 'https://www.youtube.com/watch?v=0XVbn86Btj0', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-bird-dogs', 'Bird Dogs', 'posture', 'core,glutes,lower_back', 'bodyweight', 'On all fours, extend opposite arm and leg. Keep your hips level, don''t rotate. This builds the cross-body stability that protects your spine and powers rotational movement.', 'https://www.youtube.com/watch?v=wGh2fZU20-M', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-cat-cow', 'Cat-Cow', 'posture', 'spine,core', 'bodyweight', 'Arch up (cat), then drop belly and look up (cow). Move slowly with your breath. This warms up your entire spine and teaches segmental movement through each vertebra.', 'https://www.youtube.com/watch?v=y39PrKY_4JM', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pigeon-stretch', 'Pigeon Stretch', 'posture', 'glutes,hip_flexors', 'bodyweight', 'Front leg bent across in front of you, back leg extended behind. Sink the hips down only as far as is comfortable and breathe. You should feel a stretch in the outside of the front hip and glute, nothing in the knee. Hold 45s each side. Don''t force it.', 'https://www.youtube.com/watch?v=Ms6VMXPq2uU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-cossack-squats', 'Cossack Squats', 'posture', 'adductors,hips,ankles', 'bodyweight', 'Wide stance, shift to one side and sink deep. The other leg stays straight. This builds the hip mobility you need for powerful kicks and low guards.', 'https://www.youtube.com/watch?v=tpczTeSkHz0', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-90-90-hip-switches', '90/90 Hip Switches', 'posture', 'hips,glutes', 'bodyweight', 'Sit with both legs bent at 90 degrees, one in front and one to the side. Rotate the knees over to switch sides, smooth and controlled, hands behind you if needed. You should feel the hips turning in and out, nothing pinching. Hip rotation range for kicks.', 'https://www.youtube.com/watch?v=qq_Z7sAmVrA', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-psoas-stretch', 'Psoas March', 'posture', 'psoas,hip_flexors', 'bodyweight', 'On your back, band around the feet. Slow marching with the trunk braced, one knee toward the chest at a time. Hip flexor control and range.', 'https://www.youtube.com/watch?v=vHIJgPO3p9Q', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-wall-hip-cars', 'Wall Hip CARs', 'posture', 'hips', 'wall', 'Hands on wall for balance. Lift knee high and rotate outward in the largest circle you can control, then reverse. This builds the usable hip range that translates to kicks.', 'https://www.youtube.com/watch?v=5kM-o61Z14I', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-sciatic-nerve-glide', 'Sciatic Nerve Glide', 'posture', 'sciatic_nerve,hamstrings', 'bodyweight', 'Seated, straighten one leg and gently rock the foot between pointed and flexed. Small, easy range, never into pain. If pain or tingling runs down the leg, stop and see a clinician.', 'https://www.youtube.com/watch?v=OMbKv94Bu_U', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-crocodile-breathing', 'Crocodile Breathing', 'mobility', 'diaphragm,ribcage', 'bodyweight', 'Face down, forehead on your hands. Slow breaths into the low back and sides. A calm way to start; it eases tension rather than fixing anything.', 'https://www.youtube.com/watch?v=2ibSb6jQ3Ec', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-foam-roll-thoracic', 'Thoracic Extension on Foam Roller', 'mobility', 'thoracic_spine,upper_back', 'foam roller', 'Roller across the upper back, hands behind the head. Let the upper back extend over the roller, ribs down, low back stays out of it. Try 2-3 spots. Builds upper-back extension range and feels good; it does not fix posture on its own.', 'https://www.youtube.com/watch?v=WTwJNj1IjXI', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-prone-cobra', 'Prone Cobra', 'mobility', 'posterior_chain,lower_traps,rear_delts', 'bodyweight', 'Lie face down, lift the chest and arms, thumbs up, shoulder blades back and down. Hold 3s. Trains the upper-back muscles.', 'https://www.youtube.com/watch?v=LWDUyq4TRMU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-external-rotation', 'Band External Rotations', 'mobility', 'rear_delts,rotator_cuff', 'band', 'Elbow tucked to your side, rotate the forearm outward against the band. Slow. Trains the rotator cuff (infraspinatus and teres minor).', 'https://www.youtube.com/watch?v=lw5jkvrLwVw', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-couch-stretch', 'Couch Stretch', 'mobility', 'hip_flexors,quads', 'bodyweight,couch', 'Back foot on the couch, front knee forward, tuck the tailbone and squeeze the back glute. 30s each side. A strong hip flexor stretch; optional.', 'https://www.youtube.com/shorts/TML8Vqy-ACQ', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-worlds-greatest-stretch', 'World''s Greatest Stretch', 'mobility', 'hips,groin,thoracic_spine', 'bodyweight', 'Lunge, hand inside front foot, rotate top arm to ceiling. 30s each side. Opens hip, groin, and thoracic spine in one move.', 'https://www.youtube.com/watch?v=-CiWQ2IvY34', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-ankle-cars', 'Ankle CARs', 'mobility', 'ankles', 'bodyweight', 'Controlled articular rotations. Slow full circles, both directions, each ankle. Dorsiflexion quality drives squat depth and kick mechanics.', 'https://www.youtube.com/watch?v=6iht_ecV1Go', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-walking-knee-hugs', 'Walking Knee Hugs', 'mobility', 'hip_flexors,glutes', 'bodyweight', 'Step forward, lift one knee and hug it to your chest for a beat while standing tall on the other leg, then release and walk through. 6 per side. You should feel a stretch in the glute and back of the hugged leg. A dynamic hip warm-up.', 'https://www.youtube.com/watch?v=GVU4paANHoE', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-walking-quad-pulls', 'Walking Quad Pulls', 'mobility', 'quads,hip_flexors', 'bodyweight', 'Step, grab same-side ankle behind you, squeeze glute for a beat, walk through. 6 per side. Lengthens rectus femoris on the move.', 'https://www.youtube.com/watch?v=yGN2Z6XkWNQ', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-spiderman-tspine', 'Spiderman + T-Spine Rotation', 'mobility', 'hips,adductors,thoracic_spine', 'bodyweight', 'Low lunge, hand inside front foot, rotate top arm to ceiling and follow with your eyes. 5 per side. Hip, hamstring, and thoracic rotation in one.', 'https://www.youtube.com/watch?v=nOqMAsvRJ90', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lateral-lunges', 'Lateral Lunges', 'mobility', 'adductors,glutes,quads', 'bodyweight', 'Step wide, sit into one hip, other leg stays straight. 6 per side. Adductor and glute medius — frontal plane prep runners skip.', 'https://www.youtube.com/watch?v=4NlJdSzHeUg', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-a-skips', 'A-Skips', 'mobility', 'calves,hip_flexors,glutes', 'bodyweight', 'Light skip, drive lead knee to 90, opposite arm swings. 30s easy. Primes stride mechanics. Stay bouncy, not hard.', 'https://www.youtube.com/watch?v=GQg9L28bi1g', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-toe-touch-forward-fold', 'Toe-Touch Forward Fold', 'posture', 'hamstrings,calves,low_back', 'bodyweight', 'Feet hip-width, fold from the hips, let the head hang. Soft knees if the hamstrings grip. 45s. Full posterior chain opens in one move.', 'https://www.youtube.com/watch?v=tlVT41u7bUQ', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-butterfly-stretch', 'Butterfly Stretch', 'posture', 'adductors,hips', 'bodyweight', 'Sit with the soles of the feet together and let the knees fall open. Sit tall, then fold forward gently from the hips. You should feel a stretch along the inner thighs. 60s, breathing easy.', 'https://www.youtube.com/watch?v=b2DBNGlZfpo', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-standing-quad-stretch', 'Standing Quad Stretch', 'posture', 'quads,hip_flexors', 'bodyweight', 'Stand tall, a hand on a wall if needed. Grab the ankle behind you, knees together, and squeeze the back glute. You should feel a stretch in the front of the thigh and hip. 30s each side.', 'https://www.youtube.com/watch?v=UGEpQ1BRx-4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-standing-calf-stretch', 'Standing Calf Stretch', 'posture', 'calves,achilles', 'bodyweight', 'Hands on wall, back leg straight, press the heel down. 30s each side. Gastrocnemius and Achilles, the chain that takes every step of impact.', 'https://www.youtube.com/watch?v=f1HzSAuB-Vw', 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f01', 'Jab → Cross', 'foundation', 'foundation', 1, 0, 'boxing', 'Rotate the hip fully on the cross. Power comes from the ground, not the arm.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f02', 'Jab → Cross → Hook', 'foundation', 'foundation', 1, 0, 'boxing', 'Keep the hook tight at 90 degrees. Don''t let the elbow flare wide.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f03', 'Double Jab → Cross', 'foundation', 'foundation', 1, 0, 'boxing', 'The second jab sets up range. Don''t rush it. Make both jabs snap.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f04', 'Jab → Cross → Hook → Cross', 'foundation', 'foundation', 1, 0, 'boxing', 'Return hands to guard between each strike. Reset beats speed.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f05', 'Jab → Body Cross → Lead Hook', 'foundation', 'foundation', 1, 0, 'boxing', 'Drop your level for the body cross by bending the knees, not the waist.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-f06', 'Lead Hook → Cross', 'foundation', 'foundation', 1, 0, 'boxing', 'Weight shifts from lead to rear on the cross. Feel the transfer through the hips.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w01', 'Jab → Cross → Rear Roundhouse', 'weapons', 'weapons', 0, 0, 'boxing,kicks', 'Turn the hip over on the kick. Your belly button should face the bag at impact.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w02', 'Jab → Cross → Switch Kick', 'weapons', 'weapons', 0, 0, 'boxing,kicks', 'Snap the switch fast. The kick power comes from the hip switch, not the leg.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w03', 'Jab → Cross → Low Kick', 'weapons', 'weapons', 0, 0, 'boxing,kicks', 'Chop down through the target on the low kick. Shin contact, not the foot.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w04', 'Jab → Cross → Hook → Low Kick', 'weapons', 'weapons', 0, 0, 'boxing,kicks', 'Plant and reset after the hook before throwing the low kick.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w05', 'Jab → Jab → Teep', 'weapons', 'weapons', 0, 0, 'boxing,defensive', 'Push through the teep with the hip. Snap the foot back fast to guard.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w06', 'Jab → Cross → Body Kick', 'weapons', 'weapons', 0, 0, 'boxing,kicks', 'Lean slightly away from the kick for counterbalance. Arm swings down.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-w07', 'Teep → Jab → Cross', 'weapons', 'weapons', 0, 0, 'boxing,defensive', 'Use the teep to create range, then step in behind the jab.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl01', 'Cross → Hook → Cross → Left Kick', 'flow', 'flow', 0, 0, 'boxing,kicks', 'Stay on the balls of your feet throughout. Don''t plant flat between strikes.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl02', 'Double Jab → Cross → Right Kick', 'flow', 'flow', 0, 0, 'boxing,kicks', 'The double jab walks you into range for the kick. Don''t overcommit the cross.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl03', 'Inside Low Kick → Cross → Hook', 'flow', 'flow', 0, 0, 'boxing,kicks', 'Step at an angle with the inside low kick to open the line for the cross.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl04', 'Jab → Cross → Lead Hook Body → Rear Roundhouse', 'flow', 'flow', 0, 0, 'boxing,kicks', 'Change levels smoothly. Dip for the body hook, then rise into the kick.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl05', 'Right Leg Kick → Jab → Cross → Left Leg Kick', 'flow', 'flow', 0, 0, 'boxing,kicks', 'Return hands to guard between the opening kick and the jab.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-fl06', 'Jab → Cross → Hook → Pivot Out', 'flow', 'flow', 0, 0, 'boxing', 'Pivot on the lead foot. Exit at 45 degrees, not straight back.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d01', 'Feint Jab → Cross → Left Kick → Step Out', 'deception', 'deception', 0, 0, 'boxing,kicks,defensive', 'Make the feint convincing. Commit the shoulder, then fire the cross off the reaction.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d02', 'Jab → Feint Teep → Cross → Hook → Reset', 'deception', 'deception', 0, 0, 'boxing,defensive', 'Lift the knee for the feint teep like a real one. The sell is in the chamber.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d03', 'Feint Low Kick → Cross → Hook → Left Body Kick', 'deception', 'deception', 0, 0, 'boxing,kicks,defensive', 'The feint drops their guard low. Attack high off their reaction.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d04', 'Jab → Check → Cross → Hook → Right Kick', 'deception', 'deception', 0, 0, 'boxing,kicks,defensive', 'Lift the check sharp and fast, then immediately drive the cross.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d05', 'Cross → Hook → Cross → Step Off', 'deception', 'deception', 0, 0, 'boxing,defensive', 'The step off is the exit. Don''t admire the work. Move your feet.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d06', 'Teep → Step Back → Cross → Hook → Low Kick', 'deception', 'deception', 0, 0, 'boxing,kicks,defensive', 'Use the step back to draw them forward, then punish the advance.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-d07', 'Slip → Cross → Hook → Low Kick', 'deception', 'deception', 0, 0, 'boxing,kicks,defensive', 'Slip with the knees, not the waist. Keep your eyes on the target.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-m01', 'Double Jab → Feint → Right Kick → Reset', 'mastery', 'mastery', 0, 0, 'boxing,kicks,defensive', 'The feint between the jab and kick creates hesitation. Timing over power.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-m02', 'Jab → Cross → Hook → Check → Teep', 'mastery', 'mastery', 0, 0, 'boxing,defensive', 'Transition from offense to defense and back. The check resets your stance.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-m03', 'Jab → Cross → Feint → Low Kick → Exit', 'mastery', 'mastery', 0, 0, 'boxing,kicks,defensive', 'The feint before the low kick freezes the guard high. Attack what opens.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-m04', 'Feint Teep → Cross → Hook → Cross → Reset', 'mastery', 'mastery', 0, 0, 'boxing,defensive', 'Three-piece after the feint must flow without pause. Commit to the rhythm.', 0, 0, 1776995558);
INSERT OR REPLACE INTO combos (id, text, tier, level, unlocked, mastery_score, techniques, form_tips, is_favourite, times_sharp, created_at) VALUES ('combo-m05', 'Parry → Cross → Lead Hook → Rear Kick', 'mastery', 'mastery', 0, 0, 'boxing,kicks,defensive', 'The parry is active. Pull the jab offline, then counter immediately.', 0, 0, 1776995558);
