INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-row', 'Band Row', 'strength', 'back,biceps,rear_delts', 'band', 'Anchor the band under the feet or around a fixed post. Pull elbows back, pause, and keep ribs down.', 'https://www.youtube.com/watch?v=gm2_6DX_0Bw', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-good-morning', 'Band Good Morning', 'strength', 'hamstrings,glutes,lower_back', 'band', 'Stand on the band with it behind the neck or shoulders. Push hips back, keep spine long, then squeeze glutes to stand.', 'https://www.youtube.com/watch?v=CTRaCzE8pWU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-chest-press', 'Band Chest Press', 'strength', 'chest,shoulders,triceps', 'band', 'Press the band forward from chest height. Keep shoulders down and ribs stacked.', 'https://www.youtube.com/watch?v=2XDzSxSddXU', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-band-curl', 'Band Curl', 'strength', 'biceps,forearms', 'band', 'Stand on the band, pin elbows near the ribs, curl without swinging.', 'https://www.youtube.com/watch?v=3Jqd9n2Poek', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-db-bench-press', 'DB Bench Press', 'strength', 'chest,shoulders,triceps', 'dumbbell,bench', 'Set shoulder blades on the bench. Lower dumbbells under control, press without letting shoulders roll forward.', 'https://www.youtube.com/watch?v=VmB1G1K7v94', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-goblet-squat', 'Goblet Squat', 'strength', 'quads,glutes,core', 'dumbbell,kettlebell', 'Hold the weight high against the chest. Sit between the hips, keep torso tall, and drive through the floor.', 'https://www.youtube.com/watch?v=MeIiIdhvXT4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-db-rdl', 'DB Romanian Deadlift', 'strength', 'hamstrings,glutes,lower_back', 'dumbbell', 'Dumbbells track down the legs. Hips move back, knees stay soft, spine stays long.', 'https://www.youtube.com/watch?v=JCXUYuzwNrM', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-db-ohp', 'DB Overhead Press', 'strength', 'shoulders,triceps,core', 'dumbbell', 'Brace ribs down. Press dumbbells overhead without leaning back.', 'https://www.youtube.com/watch?v=qEwKCR5JCog', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lat-pulldown', 'Lat Pulldown', 'strength', 'back,biceps', 'machine,cable', 'Pull elbows down toward ribs. Chest tall, no swinging.', 'https://www.youtube.com/watch?v=CAwf7n6Luuc', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-hamstring-curl', 'Hamstring Curl', 'strength', 'hamstrings', 'machine', 'Curl under control, pause, and return slowly without lifting the hips.', 'https://www.youtube.com/watch?v=1Tq3QdYUuHs', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-push-up', 'Push-Up', 'strength', 'chest,shoulders,triceps,core', 'bodyweight', 'Straight line from head to heels. Lower with control, press the floor away.', 'https://www.youtube.com/watch?v=IODxDxX7oi4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-pike-push-up', 'Pike Push-Up', 'strength', 'shoulders,triceps,core', 'bodyweight', 'Hips high, head travels toward the floor between the hands. Press back up without collapsing the neck.', 'https://www.youtube.com/watch?v=x7_IW_Su2-4', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-tempo-squat', 'Tempo Squat', 'strength', 'quads,glutes,core', 'bodyweight,band', 'Descend for three seconds, pause briefly, and stand with control.', 'https://www.youtube.com/watch?v=aclHkVaku9U', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-reverse-lunge', 'Reverse Lunge', 'strength', 'quads,glutes,hamstrings', 'bodyweight,dumbbell,band', 'Step back, keep front foot planted, and stand through the front leg.', 'https://www.youtube.com/watch?v=QOVaHwm-Q6U', 1776995558);
INSERT OR REPLACE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-single-leg-rdl', 'Single-Leg RDL', 'strength', 'hamstrings,glutes,balance', 'bodyweight,dumbbell', 'Hinge on one leg with hips square. Reach long, then stand by squeezing the glute.', 'https://www.youtube.com/watch?v=YMx4z2itkx8', 1776995558);

-- The Library's content (page 60), the same rows as drizzle/0038_library_content.sql.
-- Appended to seed.sql so a fresh seed (INSERT OR REPLACE) keeps the approved content.
UPDATE exercises SET name = 'Front Squat', form_cues = 'Bar on the front of the shoulders, elbows high. Sit straight down between the hips, then stand up through the whole foot.', tips = 'Fingertips under the bar are enough; a full grip is not needed. | If the elbows drop, the bar rolls forward. Lift the elbows first out of the bottom. | Small plates under the heels help if the ankles are tight.', form_video_url = 'https://www.youtube.com/shorts/4n9HM7VabC0', video_start_sec = NULL, video_source = 'Squat University', video_title = 'How To Front Squat (HIGHER ELBOWS!)', video_length = '1:00', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=uQeCK1vfj4E', alt_video_source = 'Squat University', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Your main squat. Goblet squats in weeks 1-2, front squat from week 3. Sets of 8 with 2-3 reps left; your squat max is worked out from these sets.' WHERE id = 'ex-front-squat';
UPDATE exercises SET name = 'Bench Press', form_cues = 'Shoulder blades back and down, feet flat. Lower the bar to the lower chest, then press it back up over the shoulders.', tips = 'Grip so the forearms are vertical at the bottom. | Touch the chest lightly, no bounce. | Keep the butt on the bench.', form_video_url = 'https://www.youtube.com/shorts/Oy85yiXfYkg', video_start_sec = NULL, video_source = 'Squat University', video_title = 'How To Bench Press With PERFECT Form', video_length = '0:54', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=W3GUNLnu_aQ', alt_video_source = 'Alan Thrall (Untamed Strength)', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Main press. 2-3 hard sets, RPE 6-7 early in Block Zero, never to failure.' WHERE id = 'ex-bench-press';
UPDATE exercises SET name = 'Overhead Press', form_cues = 'Bar on the front of the shoulders, grip just outside them. Squeeze the glutes, press straight up and move the head through once the bar passes it.', tips = 'Ribs down. Do not lean back to finish the rep. | Lock out with the bar over the middle of the foot. | On a sore-back day the coach swaps in the DB press.', form_video_url = 'https://www.youtube.com/watch?v=wJlKUo2-P4o', video_start_sec = NULL, video_source = 'Alan Thrall (Untamed Strength)', video_title = 'CORRECT STARTING POSITION FOR THE PRESS (Standing Overhead)', video_length = '2:42', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=eNFXEEdfQp4', alt_video_source = 'Alan Thrall (Untamed Strength)', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Fighter-phase press. Builds shoulder strength for the guard and clinch. Swapped for DB press when back today is 2 or lower.' WHERE id = 'ex-ohp';
UPDATE exercises SET name = 'Bent Over Row', form_cues = 'Hinge until the torso is near 45 degrees, back flat. Pull the bar to the lower ribs, pause, lower it under control.', tips = 'Brace before every rep, not just the first. | If the torso rises to finish the rep, the weight is too heavy. | You should feel the upper and middle back, not the low back.', form_video_url = 'https://www.youtube.com/watch?v=RQU8wZPbioA', video_start_sec = NULL, video_source = 'Alan Thrall (Untamed Strength)', video_title = 'How To Barbell Row', video_length = '5:17', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=5Qqw-aXagNs', alt_video_source = 'E3 Rehab Exercise Library', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Main row from week 3 (Dumbbell Row before that). Balances all the pressing and punching.' WHERE id = 'ex-bent-over-row';
UPDATE exercises SET name = 'Romanian Deadlift', form_cues = 'Soft knees, push the hips back. Slide the bar down the thighs until the hamstrings stretch, then squeeze the glutes to stand.', tips = 'The bar stays touching the legs the whole way. | Stop where the back would start to round, usually just below the knee. | Slow down, normal speed up.', form_video_url = 'https://www.youtube.com/shorts/eHLuROg0FSI', video_start_sec = NULL, video_source = 'Squat University', video_title = 'How To Romanian Deadlift (RDL)', video_length = '0:53', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=jEy_czb3RKA', alt_video_source = 'Alan Thrall (Untamed Strength)', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Fighter phase weeks 1-2 hinge, before Block Pull. Back today 2 or lower: glute bridges instead.' WHERE id = 'ex-rdl';
UPDATE exercises SET name = 'Block Pull', form_cues = 'Bar on blocks just below the knee. Set up like a deadlift: bar over mid-foot, back flat, then push the floor away.', tips = 'Pull the slack out of the bar before it leaves the blocks. | Finish by standing tall, not leaning back. | Lower it to the blocks under control.', form_video_url = 'https://www.youtube.com/watch?v=jfSxbT-65ow', video_start_sec = NULL, video_source = 'Alan Thrall (Untamed Strength)', video_title = 'The Block/Rack Pull: Untamed Special', video_length = '5:36', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=PMqH4cOoN_A', alt_video_source = 'Starting Strength', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'Main hinge from week 3 of Block Zero. Shorter range means less load on the low back while you build the pull.' WHERE id = 'ex-block-pull';
