UPDATE techniques SET cue = 'Lift the knee, then push the ball of the foot through the target by driving the hip forward. Bring the foot straight back.', tips = 'Hip drives, not the leg. | Lean back slightly as it lands. | Hands stay up.', form_video_url = 'https://www.youtube.com/watch?v=7rlAj7pyvnE', video_start_sec = NULL, video_source = 'Sean "Muay Thai Guy" Fagan', video_title = 'How To Throw A Teep/Push Kick Tutorial - Basic Muay Thai Techniques', video_length = '1:07', video_status = 'live', video_checked_at = 1792469580, alt_video_url = 'https://www.youtube.com/watch?v=BMQ4xAVKICU', alt_video_source = 'Sylvie von Duuglas-Ittu - Muay Thai', alt_video_status = 'live', tiktok_url = NULL, coach_hint = 'In 12 combos. Your range finder.' WHERE id = 'tech-teep';
